	async function deleteCurrentPicture(uid, field) {
		if (meta.config['profile:keepAllUserImages']) {
			return;
		}
		const value = await User.getUserField(uid, field);
		const uploadPath = getLocalProfilePath(value, uid, field === 'cover:url' ? 'cover' : 'avatar');
		if (uploadPath) {
			await deleteLocalFile(uploadPath);
		}
	}

	function validUid(uid) {
		return (typeof uid === 'number' && Number.isSafeInteger(uid) && uid > 0) ||
			(typeof uid === 'string' && /^[1-9]\d*$/.test(uid) && Number.isSafeInteger(Number(uid)));
	}

	function getLocalProfilePath(url, uid, type) {
		if (!validUid(uid) || typeof url !== 'string') {
			return false;
		}
		const prefix = `${nconf.get('relative_path')}/assets/uploads/profile/`;
		if (!url.startsWith(prefix)) {
			return false;
		}
		const filename = url.slice(prefix.length);
		const extension = path.extname(filename).slice(1).toLowerCase();
		const stem = filename.slice(0, -(extension.length + 1));
		const ownStem = `${uid}-profile${type}`;
		const allowedExtensions = new Set(User.getAllowedProfileImageExtensions().concat(['png', 'jpeg', 'jpg', 'bmp']));
		if (filename !== path.basename(filename) || !allowedExtensions.has(extension) ||
			(stem !== ownStem && !new RegExp(`^${ownStem}-\\d+$`).test(stem))) {
			return false;
		}
		const folder = path.resolve(nconf.get('upload_path'), 'profile');
		return path.join(folder, filename);
	}

	async function getLocalProfilePaths(uid, type) {
		if (!validUid(uid)) {
			throw new Error('[[error:invalid-uid]]');
		}
		const folder = path.resolve(nconf.get('upload_path'), 'profile');
		let filenames;
		try {
			filenames = await fs.promises.readdir(folder);
		} catch (err) {
			if (err.code === 'ENOENT') {
				return [];
			}
			throw err;
		}
		return filenames.map(filename => getLocalProfilePath(
			`${nconf.get('relative_path')}/assets/uploads/profile/${filename}`, uid, type
		)).filter(Boolean);
	}

	async function deleteLocalFile(localPath) {
		try {
			await fs.promises.unlink(localPath);
		} catch (err) {
			if (err.code !== 'ENOENT') {
				throw err;
			}
		}
	}

	async function removeLocalProfileFiles(uid, type, url) {
		const paths = await getLocalProfilePaths(uid, type);
		const currentPath = getLocalProfilePath(url, uid, type);
		if (currentPath) {
			paths.push(currentPath);
		}
		await Promise.all([...new Set(paths)].map(deleteLocalFile));
	}

	User.getLocalCoverPath = async function (uid) {
		return (await getLocalProfilePaths(uid, 'cover'))[0] || false;
	};

	User.getLocalAvatarPath = async function (uid) {
		return (await getLocalProfilePaths(uid, 'avatar'))[0] || false;
	};

	function validateUpload(data, maxSize, allowedTypes) {
		if (!data.imageData) {
			throw new Error('[[error:invalid-data]]');
		}
		const size = image.sizeFromBase64(data.imageData);
		if (size > maxSize * 1024) {
			throw new Error(`[[error:file-too-big, ${maxSize}]]`);
		}

		const type = image.mimeFromBase64(data.imageData);
		if (!type || !allowedTypes.includes(type)) {
			throw new Error('[[error:invalid-image]]');
		}
	}

	async function convertToPNG(path) {
		const convertToPNG = meta.config['profile:convertProfileImageToPNG'] === 1;
		if (!convertToPNG) {
			return path;
		}
		const newPath = await image.normalise(path);
		await file.delete(path);
		return newPath;
	}

	function generateProfileImageFilename(uid, extension) {
		const convertToPNG = meta.config['profile:convertProfileImageToPNG'] === 1;
		return `${uid}-profileavatar-${Date.now()}${convertToPNG ? '.png' : extension}`;
	}

	User.removeCoverPicture = async function (uid) {
		if (!validUid(uid)) {
			throw new Error('[[error:invalid-uid]]');
		}
		const url = await User.getUserField(uid, 'cover:url');
		await removeLocalProfileFiles(uid, 'cover', url);
		await db.deleteObjectFields(`user:${uid}`, ['cover:url', 'cover:position']);
		return { success: true };
	};

	User.removeProfileImage = async function (uid) {
		if (!validUid(uid)) {
			throw new Error('[[error:invalid-uid]]');
		}
		const userData = await User.getUserFields(uid, ['uploadedpicture', 'picture']);
		await removeLocalProfileFiles(uid, 'avatar', userData.uploadedpicture);
		await User.setUserFields(uid, {
			uploadedpicture: '',
			picture: userData.picture === userData.uploadedpicture ? '' : userData.picture,
		});
		return userData;
	};
